/**
 * v2 automation trigger factories. Each returns a {@link TriggerDef}: the wire
 * trigger envelope (discriminated by kind, mirroring v1's `serializeStoredTrigger`)
 * plus the typed `ctx.trigger` shape. Aspect/field references are `CatalogRef`
 * tokens, resolved at deploy.
 *
 * `onDemand` reuses v1's typed-schema machinery + wire serializer directly —
 * it's reference-model-agnostic (typed params, no id resolution), so there's
 * nothing to retarget; it relocates to a shared home at the cutover.
 */
import type { ApprovalChainRef, AppOrElementRef, DatamineRef, FieldRef } from "../../catalog/index.js";
import type { UnsafePlatformId } from "../../core/platform-id.js";
